import{_ as t,o as a,c as i,a0 as l}from"./chunks/framework.DB31oXgM.js";const f=JSON.parse('{"title":"08 - Security & Failure Modes: Rollback Netcode Server","description":"","frontmatter":{},"headers":[],"relativePath":"08-security-and-failure-modes.md","filePath":"08-security-and-failure-modes.md"}'),r={name:"08-security-and-failure-modes.md"};function s(n,e,o,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_08-security-failure-modes-rollback-netcode-server" tabindex="-1">08 - Security &amp; Failure Modes: Rollback Netcode Server <a class="header-anchor" href="#_08-security-failure-modes-rollback-netcode-server" aria-label="Permalink to &quot;08 - Security &amp; Failure Modes: Rollback Netcode Server&quot;">​</a></h1><h2 id="_1-threat-model-mitigations-specified" tabindex="-1">1. Threat Model &amp; Mitigations [Specified] <a class="header-anchor" href="#_1-threat-model-mitigations-specified" aria-label="Permalink to &quot;1. Threat Model &amp; Mitigations [Specified]&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Threat</th><th style="text-align:left;">Attack Vector</th><th style="text-align:left;">System Defense Mechanism</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Input Forgery / Teleportation</strong></td><td style="text-align:left;">Modified client sends impossible coordinate deltas</td><td style="text-align:left;">Server-authoritative physics: client only sends input bitmasks; server calculates all positions</td></tr><tr><td style="text-align:left;"><strong>Speed Hacking / Clock Manipulation</strong></td><td style="text-align:left;">Client accelerates local tick rate to generate excessive frames</td><td style="text-align:left;">NTP clock sync rate limits: server rejects inputs $&gt; 4$ frames ahead of server clock</td></tr><tr><td style="text-align:left;"><strong>UDP Replay / Packet Injection</strong></td><td style="text-align:left;">Malicious actor captures and replays valid input packets</td><td style="text-align:left;">Monotonically increasing frame indices + 32-bit ephemeral session tokens</td></tr><tr><td style="text-align:left;"><strong>Denial of Service (Flooding)</strong></td><td style="text-align:left;">UDP packet flooding targeted at game socket</td><td style="text-align:left;">Token-bucket rate limiting per IP + early drop of invalid session tokens</td></tr><tr><td style="text-align:left;"><strong>Desync Exploitation</strong></td><td style="text-align:left;">Client intentionally induces desync to force state resets</td><td style="text-align:left;">Instant desync detection: server logs incident and kicks client if divergence persists</td></tr></tbody></table><h2 id="_2-failure-modes-graceful-degradation-specified" tabindex="-1">2. Failure Modes &amp; Graceful Degradation [Specified] <a class="header-anchor" href="#_2-failure-modes-graceful-degradation-specified" aria-label="Permalink to &quot;2. Failure Modes &amp; Graceful Degradation [Specified]&quot;">​</a></h2><ol><li><strong>Severe Packet Loss (&gt; 40%)</strong>: <ul><li>The 5-frame redundant input bundling recovers transient drops. If loss exceeds recovery capability, the engine pauses forward prediction and displays a &quot;Network Lag Reconnecting&quot; banner.</li></ul></li><li><strong>PostgreSQL Telemetry Outage</strong>: <ul><li>The server buffers input logs in an in-memory queue. If Postgres becomes unavailable, active gameplay continues uninterrupted; analytics logs are drained asynchronously upon database recovery.</li></ul></li><li><strong>AI Service Failure</strong>: <ul><li>If the Isolation Forest or LLM endpoints time out, the server falls back to static hardcoded thresholds without blocking any simulation ticks.</li></ul></li></ol>',5)])])}const p=t(r,[["render",s]]);export{f as __pageData,p as default};
